/// Find current source-dump metadata by exact display name.
pub fn champions_current_species(name: &str) -> Option<ChampionReferenceSpecies> {
    CHAMPIONS_CURRENT_SPECIES
        .iter()
        .copied()
        .find(|entry| entry.name == name)
}
